#!/usr/bin/env node
// Embed the agent environment (agent/env.js) and the engine files it needs
// into a Swift source file, so the macOS app runs exactly the JavaScript the
// web game and the agent CLI run.
//
//   node macos/scripts/embed-engine.js          # rewrite the generated file
//   node macos/scripts/embed-engine.js --check  # exit 1 if it is out of date
//
// macos/embed.test.js runs the check under `npm test`, so the copy can't drift.
'use strict';
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..', '..');
const OUT = path.join(ROOT, 'macos', 'Sources', 'BlackjackCore', 'EngineJS.generated.swift');

/** Repo-relative files that `rel` require()s, followed transitively. */
function closure(rel, seen = new Set()) {
  const text = fs.readFileSync(path.join(ROOT, rel), 'utf8');
  for (const m of text.matchAll(/require\('(\.{1,2}\/[^']+\.js)'\)/g)) {
    const dep = path.posix.normalize(path.posix.join(path.posix.dirname(rel), m[1]));
    if (!seen.has(dep)) { seen.add(dep); closure(dep, seen); }
  }
  return seen;
}

/**
 * What agent/env.js needs, in the order web/index.html loads the engine
 * (dependencies first), then agent/env.js itself.
 */
function sources() {
  const html = fs.readFileSync(path.join(ROOT, 'web', 'index.html'), 'utf8');
  const order = [...html.matchAll(/<script src="\.\.\/(engine\/[^"]+\.js)"><\/script>/g)].map((m) => m[1]);
  const needed = closure('agent/env.js');
  const missing = [...needed].filter((f) => !order.includes(f));
  if (missing.length) throw new Error(`web/index.html does not load ${missing.join(', ')}`);
  return [...order.filter((f) => needed.has(f)), 'agent/env.js'];
}

/** A raw string delimiter that cannot occur inside `text`. */
function delimiter(text) {
  let hashes = '#';
  while (text.includes('"""' + hashes) || text.includes('\\' + hashes)) hashes += '#';
  return hashes;
}

function render() {
  const files = sources().map((rel) => {
    const text = fs.readFileSync(path.join(ROOT, rel), 'utf8');
    const d = delimiter(text);
    return `        (name: "${rel}", source: ${d}"""\n${text.replace(/\n$/, '')}\n"""${d}),`;
  });
  return [
    '// GENERATED by macos/scripts/embed-engine.js from engine/ and agent/env.js. Do not edit;',
    '// change the JavaScript and run `node macos/scripts/embed-engine.js`.',
    '',
    'enum EngineJS {',
    '    /// Evaluated in this order into one JSContext.',
    '    static let files: [(name: String, source: String)] = [',
    ...files,
    '    ]',
    '}',
    '',
  ].join('\n');
}

function main() {
  const want = render();
  if (process.argv.includes('--check')) {
    const have = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : '';
    if (have !== want) {
      console.error(`${path.relative(ROOT, OUT)} is out of date: run node macos/scripts/embed-engine.js`);
      process.exit(1);
    }
    return;
  }
  fs.writeFileSync(OUT, want);
  console.log(`wrote ${path.relative(ROOT, OUT)} (${sources().length} files)`);
}

if (require.main === module) main();
module.exports = { render, sources, OUT };
